struct Pose { simd_float3 p;simd_quatf q; };
struct MeshTemplate { SCNGeometry* geometry;SCNGeometrySource* weights;SCNGeometrySource* indices; };
struct VisualTemplate {std::shared_ptr<const mu::viewer::ActorVisual> visual;std::vector<MeshTemplate> meshes;std::array<std::vector<std::vector<Pose>>,2> attack;std::vector<std::vector<Pose>> idle,walk,death;};
struct Rig {std::shared_ptr<VisualTemplate> model;SCNNode* node;NSArray<SCNNode*>* joints;mu::viewer::MotionTrack motion;unsigned tx=0,ty=0;std::uint64_t revision=0,actionRevision=0;unsigned attackVariant=0;double attackAge=0,attackDuration=0;double phase=0,blend=.12;bool walking=false,dying=false,retired=false;double deathAge=0;std::vector<Pose> current,before,applied;mu::viewer::MotionPoint rendered;bool placed=false;};
NSImage* cocoa(const mu::assets::Image& image){auto color=CGColorSpaceCreateDeviceRGB();NSData* backing=[NSData dataWithBytes:image.rgba.data() length:image.rgba.size()];auto provider=CGDataProviderCreateWithCFData((__bridge CFDataRef)backing);auto cg=CGImageCreate(image.width,image.height,8,32,image.width*4,color,kCGImageAlphaLast|kCGBitmapByteOrder32Big,provider,nullptr,YES,kCGRenderingIntentDefault);auto out=[[NSImage alloc] initWithCGImage:cg size:NSMakeSize(image.width,image.height)];CGImageRelease(cg);CGDataProviderRelease(provider);CGColorSpaceRelease(color);return out;}
std::vector<std::vector<Pose>> samples(const std::vector<std::vector<mu::assets::Bone>>& frames){std::vector<std::vector<Pose>> result;for(auto& frame:frames){std::vector<Pose> pose;for(auto& b:frame){auto q=simd_mul(simd_quaternion(b.rotation.z,simd_make_float3(0,0,1)),simd_mul(simd_quaternion(b.rotation.y,simd_make_float3(0,1,0)),simd_quaternion(b.rotation.x,simd_make_float3(1,0,0))));pose.push_back({simd_make_float3(b.position.x,b.position.y,b.position.z),q});}result.push_back(std::move(pose));}return result;}
std::shared_ptr<VisualTemplate> prepare(std::shared_ptr<const mu::viewer::ActorVisual> visual){auto t=std::make_shared<VisualTemplate>();t->visual=visual;t->idle=samples(visual->idle);t->walk=samples(visual->walk);t->death=samples(visual->death);for(unsigned i=0;i<2;i++)t->attack[i]=samples(visual->attack[i]);NSMutableDictionary<NSValue*,NSImage*>* images=[NSMutableDictionary dictionary];
 for(auto& part:visual->parts){std::vector<SCNVector3> positions,normals;std::vector<CGPoint> uv;std::vector<uint32_t> faces;std::vector<uint16_t> binding;std::vector<float> weights;
  for(auto& face:part.mesh.faces)for(unsigned corner=0;corner<3;corner++){auto v=part.mesh.vertices.at(face.vertex[corner]);auto p=v.position;positions.push_back(SCNVector3Make(p.x,p.y,p.z));auto normal=part.mesh.normals.at(face.normal[corner]).position;normals.push_back(SCNVector3Make(normal.x,normal.y,normal.z));auto coord=part.mesh.uv.at(face.uv[corner]);uv.push_back(CGPointMake(coord[0],1-coord[1]));faces.push_back(faces.size());binding.push_back(v.bone);weights.push_back(1);}
  auto vertices=[SCNGeometrySource geometrySourceWithVertices:positions.data() count:positions.size()];auto coords=[SCNGeometrySource geometrySourceWithTextureCoordinates:uv.data() count:uv.size()];auto element=[SCNGeometryElement geometryElementWithData:[NSData dataWithBytes:faces.data() length:faces.size()*4] primitiveType:SCNGeometryPrimitiveTypeTriangles primitiveCount:faces.size()/3 bytesPerIndex:4];auto geometry=[SCNGeometry geometryWithSources:@[vertices,coords,[SCNGeometrySource geometrySourceWithNormals:normals.data() count:normals.size()]] elements:@[element]];
  auto key=[NSValue valueWithPointer:part.image.get()];auto image=images[key];if(!image){image=cocoa(*part.image);images[key]=image;}auto material=[SCNMaterial material];material.diffuse.contents=image;material.diffuse.wrapS=SCNWrapModeRepeat;material.diffuse.wrapT=SCNWrapModeRepeat;material.lightingModelName=SCNLightingModelConstant;material.doubleSided=YES;
  bool alpha=false;for(std::size_t i=3;i<part.image->rgba.size();i+=4)if(part.image->rgba[i]<255){alpha=true;break;}if(alpha){material.transparent.contents=image;material.transparent.wrapS=SCNWrapModeRepeat;material.transparent.wrapT=SCNWrapModeRepeat;material.transparencyMode=SCNTransparencyModeAOne;material.blendMode=SCNBlendModeAlpha;material.shaderModifiers=@{SCNShaderModifierEntryPointFragment:@"if (_output.color.a < 0.25) discard_fragment();"};}if(part.additive){material.transparent.contents=nil;material.blendMode=SCNBlendModeAdd;material.writesToDepthBuffer=NO;material.shaderModifiers=nil;}geometry.materials=@[material];
  auto weightSource=[SCNGeometrySource geometrySourceWithData:[NSData dataWithBytes:weights.data() length:weights.size()*4] semantic:SCNGeometrySourceSemanticBoneWeights vectorCount:weights.size() floatComponents:YES componentsPerVector:1 bytesPerComponent:4 dataOffset:0 dataStride:4];auto indexSource=[SCNGeometrySource geometrySourceWithData:[NSData dataWithBytes:binding.data() length:binding.size()*2] semantic:SCNGeometrySourceSemanticBoneIndices vectorCount:binding.size() floatComponents:NO componentsPerVector:1 bytesPerComponent:2 dataOffset:0 dataStride:2];t->meshes.push_back({geometry,weightSource,indexSource});if(part.equipment){auto holder=[SCNNode node];mu::viewer::apply_item_upgrade(holder,geometry,material,visual->effectDirectory,*part.equipment);for(SCNNode* overlay in holder.childNodes)t->meshes.push_back({overlay.geometry,weightSource,indexSource});}
 }return t;
}
Rig makeRig(std::shared_ptr<VisualTemplate> model,unsigned x,unsigned y,unsigned direction,unsigned index){Rig r;r.model=model;r.current=r.before=r.applied=r.model->idle.front();r.tx=x;r.ty=y;r.motion=mu::viewer::MotionTrack({double(x),0,-double(y),(double(direction)-1)*M_PI/4});r.motion.setSpeed(r.model->visual->moveSpeed);
    r.node=[SCNNode node];r.node.name=[NSString stringWithFormat:@"%s:%u type:%u",model->visual->npc?"npc":"entity",index,model->visual->type];r.node.opacity=r.model->visual->opacity;auto rig=[SCNNode node];rig.eulerAngles=SCNVector3Make(-M_PI/2,0,0);float scale=r.model->visual->scale*.01;rig.scale=SCNVector3Make(scale,scale,scale);[r.node addChildNode:rig];NSMutableArray<SCNNode*>* joints=[NSMutableArray array];NSMutableArray<NSValue*>* inverse=[NSMutableArray array];
    for(const auto& bone:r.model->visual->bones){[joints addObject:[SCNNode node]];[inverse addObject:[NSValue valueWithSCNMatrix4:SCNMatrix4Identity]];}
    for(unsigned i=0;i<joints.count;i++){int parent=r.model->visual->bones[i].parent;[(parent<0?rig:joints[parent]) addChildNode:joints[i]];}r.joints=joints;for(unsigned i=0;i<joints.count;i++){joints[i].simdPosition=r.current[i].p;joints[i].simdOrientation=r.current[i].q;}
    for(const auto& mesh:r.model->meshes){auto node=[SCNNode nodeWithGeometry:mesh.geometry];node.skinner=[SCNSkinner skinnerWithBaseGeometry:mesh.geometry bones:joints boneInverseBindTransforms:inverse boneWeights:mesh.weights boneIndices:mesh.indices];node.skinner.skeleton=rig;[rig addChildNode:node];}return r;}

