@implementation MuViewportRenderer {
 SCNNode* _root;NSMutableArray<SCNNode*>* _warming;mu::assets::Terrain _terrain;mu::viewer::ActorCatalog _catalog;std::map<unsigned,std::shared_ptr<VisualTemplate>> _templates;std::map<unsigned,Rig> _rigs;
 std::mutex _mutex;std::shared_ptr<const mu::client::ViewportSnapshot> _pending;std::uint64_t _revision;bool _received;
}
- (instancetype)initWithRoot:(SCNNode*)root terrain:(const mu::assets::Terrain&)terrain catalog:(const mu::viewer::ActorCatalog&)catalog{self=[super init];if(self){_root=root;_terrain=terrain;_catalog=catalog;_revision=0;_received=false;_warming=[NSMutableArray array];for(auto& pair:catalog){auto model=prepare(pair.second);_templates.emplace(pair.first,model);auto rig=makeRig(model,0,0,0,0);[_warming addObject:rig.node];}}return self;}
- (NSArray*)preparationObjects{return _warming;}
- (void)releasePreparationObjects{[_warming removeAllObjects];}
- (void)submit:(std::shared_ptr<const mu::client::ViewportSnapshot>)snapshot{if(!snapshot)return;std::lock_guard<std::mutex> lock(_mutex);_pending=std::move(snapshot);}
- (void)advance:(double)dt{
 std::shared_ptr<const mu::client::ViewportSnapshot> snapshot;{std::lock_guard<std::mutex> lock(_mutex);snapshot=std::move(_pending);}
 [SCNTransaction begin];[SCNTransaction setDisableActions:YES];
 if(snapshot&&(!_received||snapshot->revision!=_revision)){_received=true;_revision=snapshot->revision;
  for(auto i=_rigs.begin();i!=_rigs.end();)if(!snapshot->entities.count(i->first)){auto& r=i->second;if(snapshot->recentDead.count(i->first)&&!r.model->death.empty()){if(!r.dying){mu::audio::play(mu::audio::monsterDeath(r.model->visual->type),.7);r.dying=true;r.phase=r.deathAge=0;r.before=r.current;r.blend=0;r.motion.clearPath();}r.retired=true;r.node.hidden=NO;++i;}else{[r.node removeFromParentNode];i=_rigs.erase(i);}}else ++i;
  for(const auto& pair:snapshot->entities){auto& e=pair.second;auto visual=_templates.find(e.kind==mu::client::EntityKind::Player?mu::viewer::dwPlayerVisualKey:e.type);if((e.kind==mu::client::EntityKind::Player&&!mu::client::is_unarmored_dw(e))||visual==_templates.end()){auto old=_rigs.find(e.index);if(old!=_rigs.end()){[old->second.node removeFromParentNode];_rigs.erase(old);}continue;}auto found=_rigs.find(e.index);
   if(found!=_rigs.end()&&(found->second.model!=visual->second||(found->second.dying&&!e.dead))){[found->second.node removeFromParentNode];_rigs.erase(found);found=_rigs.end();}
   if(found==_rigs.end()){Rig r=makeRig(visual->second,e.x,e.y,e.direction,e.index);[_root addChildNode:r.node];found=_rigs.emplace(e.index,std::move(r)).first;
   }
   auto& r=found->second;r.node.name=[NSString stringWithFormat:@"%s:%u type:%u",r.model->visual->npc?"npc":e.kind==mu::client::EntityKind::Monster?"monster":"entity",e.index,e.type];if(r.revision!=e.revision){if(e.teleport)r.motion=mu::viewer::MotionTrack({double(e.x),0,-double(e.y),(double(e.direction)-1)*M_PI/4});r.motion.setSpeed(r.model->visual->moveSpeed);r.motion.face((double(e.direction)-1)*M_PI/4);
    if(r.tx!=e.tx||r.ty!=e.ty){r.motion.clearPath();auto at=r.motion.position();unsigned sx=std::clamp(int(std::round(at.x)),0,255),sy=std::clamp(int(std::round(-at.z)),0,255);auto path=mu::viewer::find_path(_terrain.attributes,sx,sy,e.tx,e.ty);constexpr int dx[8]={-1,0,1,1,1,0,-1,-1},dy[8]={-1,-1,-1,0,1,1,1,0};if(path.size()<=14){for(auto d:path){sx+=dx[d];sy+=dy[d];r.motion.enqueue({double(sx),0,-double(sy),(double(d)-1)*M_PI/4});}}r.tx=e.tx;r.ty=e.ty;}if(e.actionRevision&&e.actionRevision!=r.actionRevision){r.actionRevision=e.actionRevision;if(e.action>=120&&e.action<=121&&!r.model->attack[e.action-120].empty()&&!e.dead){r.attackVariant=e.action-120;r.attackAge=0;r.attackDuration=r.model->visual->attackPeriod[r.attackVariant]/(25*.33);r.before=r.current;r.blend=0;r.motion.clearPath();mu::audio::play(mu::audio::monsterAttack(e.type),.7);}}if(e.dead&&!r.dying&&!r.model->death.empty()){mu::audio::play(mu::audio::monsterDeath(r.model->visual->type),.7);r.dying=true;r.phase=r.deathAge=0;r.before=r.current;r.blend=0;r.motion.clearPath();}r.node.hidden=e.dead&&r.model->death.empty();r.revision=e.revision;}
  }
 }
 for(auto& pair:_rigs){auto& r=pair.second;auto point=r.motion.advance(dt);r.attackAge+=dt;bool attacking=!r.dying&&r.attackAge<r.attackDuration;bool walk=!r.dying&&!attacking&&r.motion.moving()&&!r.model->walk.empty();if(walk!=r.walking){r.walking=walk;r.phase=0;r.before=r.current;r.blend=0;}r.phase+=dt;r.blend+=dt;
  double x=point.x+.5,y=-point.z+.5;double height=_terrain.heightAt(x,y)+r.model->visual->altitude;if(!r.placed||std::hypot(x-r.rendered.x,-y-r.rendered.z)>1e-8||std::abs(height-r.rendered.y)>1e-8)r.node.position=SCNVector3Make(x,height,-y);if(!r.placed||std::abs(point.yaw-r.rendered.yaw)>1e-8)r.node.eulerAngles=SCNVector3Make(0,point.yaw,0);r.rendered={x,height,-y,point.yaw};r.placed=true;
  r.deathAge+=r.dying?dt:0;const auto& frames=r.dying?r.model->death:attacking?r.model->attack[r.attackVariant]:walk?r.model->walk:r.model->idle;unsigned period=r.dying?r.model->visual->deathPeriod:attacking?r.model->visual->attackPeriod[r.attackVariant]:walk?r.model->visual->walkPeriod:r.model->visual->idlePeriod;double rate=25*(r.dying?.55:attacking?.33:walk?r.model->visual->walkKeySpeed:r.model->visual->idleKeySpeed),frame=(r.dying||attacking)?std::min((r.dying?r.deathAge:r.attackAge)*rate,double(period-1)):std::fmod(r.phase*rate,double(period));unsigned a=frame,b=(r.dying||attacking)?std::min(a+1,period-1):(a+1)%period;float fraction=frame-a;
  for(unsigned i=0;i<r.joints.count;i++){auto p=simd_mix(frames[a][i].p,frames[b][i].p,fraction);auto q=simd_normalize(simd_slerp(frames[a][i].q,frames[b][i].q,fraction));float blend=std::min(1.,r.blend/.12);Pose next{simd_mix(r.before[i].p,p,blend),simd_normalize(simd_slerp(r.before[i].q,q,blend))};bool changed=simd_distance_squared(next.p,r.applied[i].p)>1e-6f||1-std::abs(simd_dot(next.q.vector,r.applied[i].q.vector))>1e-7f;r.current[i]=next;if(changed){r.applied[i]=next;auto matrix=simd_matrix4x4(next.q);matrix.columns[3]=simd_make_float4(next.p.x,next.p.y,next.p.z,1);r.joints[i].simdTransform=matrix;}}
 }
 for(auto i=_rigs.begin();i!=_rigs.end();)if(i->second.retired&&i->second.deathAge>=std::max(1.,i->second.model->visual->deathPeriod/(25*.55))){[i->second.node removeFromParentNode];i=_rigs.erase(i);}else ++i;
