}
@end

@implementation MuCharacterRig {Rig _rig;NSMutableArray<MuCharacterRig*>* _links;}
- (instancetype)initWithVisual:(std::shared_ptr<const mu::viewer::ActorVisual>)visual{if((self=[super init])){_rig=makeRig(prepare(visual),0,0,0,0);SCNNode* skin=_rig.node.childNodes.firstObject;skin.eulerAngles=SCNVector3Zero;skin.scale=SCNVector3Make(visual->scale,visual->scale,visual->scale);_links=[NSMutableArray array];for(const auto& link:visual->links){if(link.second->parts.empty()||!link.second->parts.front().equipment)continue;auto item=*link.second->parts.front().equipment;unsigned bone=mu::viewer::equipment_attachment_bone(link.first,item.index,false);if(bone>=_rig.joints.count)throw std::runtime_error("Lobby attachment bone unavailable");auto child=[[MuCharacterRig alloc] initWithVisual:link.second];auto grip=[SCNNode node];grip.name=[NSString stringWithFormat:@"worn:%u",link.first];grip.simdTransform=mu::viewer::equipment_attachment_transform(link.first,item.index,false);[_rig.joints[bone] addChildNode:grip];[grip addChildNode:child.node];[child advance:0];[_links addObject:child];}}return self;}
- (SCNNode*)node{return _rig.node;}
- (void)advance:(double)time{for(MuCharacterRig* child in _links)[child advance:time];if(time>0&&_rig.model->visual->idleKeySpeed==0)return;auto& frames=_rig.model->idle;unsigned period=_rig.model->visual->idlePeriod;double frame=fmod(time*25*_rig.model->visual->idleKeySpeed,double(period));unsigned a=frame,b=(a+1)%period;float t=frame-a;for(unsigned i=0;i<_rig.joints.count;i++){auto p=simd_mix(frames[a][i].p,frames[b][i].p,t);auto q=simd_normalize(simd_slerp(frames[a][i].q,frames[b][i].q,t));_rig.joints[i].simdPosition=p;_rig.joints[i].simdOrientation=q;}}
@end
